from collections import deque


class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build_tree(vals):
    if not vals or vals[0] is None:
        return None
    root = TreeNode(vals[0])
    q = deque([root])
    i = 1
    while q and i < len(vals):
        node = q.popleft()
        if i < len(vals) and vals[i] is not None:
            node.left = TreeNode(vals[i])
            q.append(node.left)
        i += 1
        if i < len(vals) and vals[i] is not None:
            node.right = TreeNode(vals[i])
            q.append(node.right)
        i += 1
    return root


def tree_to_level(root):
    out, q = [], deque([root])
    while q:
        node = q.popleft()
        if node:
            out.append(node.val)
            q.append(node.left)
            q.append(node.right)
        else:
            out.append(None)
    while out and out[-1] is None:
        out.pop()
    return out


def parse_tree():
    return build_tree([None if t == "null" else int(t) for t in input().split()])


def fmt_level(root):
    return " ".join("null" if v is None else str(v) for v in tree_to_level(root))

from collections import defaultdict


class Solution:
    def pathSum(self, root, targetSum):
        cnt = defaultdict(int)
        cnt[0] = 1
        ans = 0

        def dfs(n, cur):
            nonlocal ans
            if not n:
                return
            cur += n.val
            ans += cnt[cur - targetSum]
            cnt[cur] += 1
            dfs(n.left, cur)
            dfs(n.right, cur)
            cnt[cur] -= 1

        dfs(root, 0)
        return ans

if __name__ == "__main__":
    root = build_tree([10, 5, -3, 3, 2, None, 11, 3, -2, None, 1])
    print(Solution().pathSum(root, 8))   # 3

